"use strict";
const { promisify } = require("node:util");
const data = { a: "alpha", b: "beta" };
function readValue(key, callback) {
  setImmediate(() => {
    if (key in data) callback(null, data[key]);
    else {
      const error = new Error(`no value for ${key}`);
      error.code = "ENOVALUE";
      callback(error);
    }
  });
}
class Store {
  constructor() {
    this.prefix = "store:";
  }
  get(key, callback) {
    process.nextTick(() => callback(null, this.prefix + key));
  }
}
function custom(callback) {
  callback(null, "plain");
}
custom[promisify.custom] = () => Promise.resolve("custom promisified");
module.exports = { readValue, Store, custom };
